SELECT x.seller_id, 'Jamuna Fashion', COUNT(*) AS c FROM (SELECT DISTINCT oi.seller_id, oi.order_id FROM order_items oi WHERE oi.seller_id IN (SELECT seller_id FROM sellers WHERE name = 'Jamuna Fashion') AND oi.order_id IN (SELECT order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2026-04-01 00:00:00' AND o.order_at < TIMESTAMP '2026-07-01 00:00:00')) x GROUP BY x.seller_id ORDER BY c DESC, x.seller_id
